ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| ImageFileName=/\\(AnyDesk|ScreenConnect\.ClientService|ScreenConnect\.WindowsClient|ScreenConnect\.ClientSetup|SplashtopStreamer|SRService|SRManager|fleetdeck_agent|fleetdeck_commander_launcher|PulsewayMonitor|tacticalrmm|rport|ngrok|rustdesk|TeamViewer|LogMeIn)\.exe$/i
| UserName!=/(^SYSTEM$|^LOCAL SERVICE$|^NETWORK SERVICE$|\$$)/i
| case {
    regex("(?i)anydesk", field=ImageFileName) | RmmFamily := "anydesk" ;
    regex("(?i)screenconnect", field=ImageFileName) | RmmFamily := "screenconnect" ;
    regex("(?i)splashtop|SRService|SRManager", field=ImageFileName) | RmmFamily := "splashtop" ;
    regex("(?i)fleetdeck", field=ImageFileName) | RmmFamily := "fleetdeck" ;
    regex("(?i)pulseway", field=ImageFileName) | RmmFamily := "pulseway" ;
    regex("(?i)tacticalrmm|rport", field=ImageFileName) | RmmFamily := "tacticalrmm" ;
    regex("(?i)ngrok", field=ImageFileName) | RmmFamily := "ngrok" ;
    regex("(?i)rustdesk", field=ImageFileName) | RmmFamily := "rustdesk" ;
    regex("(?i)teamviewer", field=ImageFileName) | RmmFamily := "teamviewer" ;
    regex("(?i)logmein", field=ImageFileName) | RmmFamily := "logmein" ;
    * | RmmFamily := "other"
  }
| groupBy([aid, ComputerName, UserName], function=[min(@timestamp, as=FirstSeen), max(@timestamp, as=LastSeen), count(field=RmmFamily, distinct=true, as=DistinctFamilies), collect([RmmFamily], multival=true)])
| DistinctFamilies >= 2
| sort(FirstSeen, order=desc)
